// Loads edition + faction config files and merges the separate points file into datasheets.
import { prepareSvg } from './icons.js';

const getJSON = path => fetch(path).then(r => {
  if (!r.ok) throw new Error(`${path}: ${r.status}`);
  return r.json();
});
// rules.json / stratagems.json are generated by tools/import_wahapedia_rules.py and may not exist
const optionalJSON = (path, fallback) => getJSON(path).catch(() => fallback);

export async function loadIndex() {
  return getJSON('data/factions/index.json');
}

const editionCache = new Map();
export async function loadEdition(id) {
  if (!editionCache.has(id)) {
    const [edition, strats] = await Promise.all([
      getJSON(`data/editions/${id}.json`),
      optionalJSON(`data/editions/${id}-stratagems.json`, { stratagems: [] }),
    ]);
    editionCache.set(id, { ...edition, coreStratagems: strats.stratagems });
  }
  return editionCache.get(id);
}

const factionCache = new Map();
export async function loadFaction(entry) {
  if (factionCache.has(entry.id)) return factionCache.get(entry.id);
  const base = `data/factions/${entry.path}`;
  const [faction, unitsFile, weaponsFile, points, rules, stratagems, images] = await Promise.all([
    getJSON(`${base}/faction.json`),
    getJSON(`${base}/units.json`),
    getJSON(`${base}/weapons.json`),
    getJSON(`${base}/points.json`),
    optionalJSON(`${base}/rules.json`, { detachments: {} }),
    optionalJSON(`${base}/stratagems.json`, { detachments: {} }),
    optionalJSON(`${base}/images.json`, { units: {} }),
  ]);
  const emblemRaw = await fetch(`${base}/emblem.svg`).then(r => (r.ok ? r.text() : null)).catch(() => null);
  const emblem = emblemRaw?.includes('<svg') ? prepareSvg(emblemRaw) : null;
  // full rule texts complement the short summaries written in faction.json
  for (const d of faction.detachments) {
    const full = rules.detachments[d.id];
    if (!full) continue;
    if (full.rule?.text?.en) d.rule = { ...d.rule, full: full.rule.text };
    for (const e of d.enhancements) {
      if (full.enhancements?.[e.id]) e.full = full.enhancements[e.id].text;
    }
  }

  const verified = new Set(points.verified ?? []);
  const globalWeapons = weaponsFile.weapons;
  const units = unitsFile.units.map(u => {
    const costs = points.units[u.id] ?? [];
    // 11th edition: some datasheets cost more from the 3rd copy in the same army
    const extra = points.unitsExtraCopies?.[u.id] ?? [];
    const sizes = (costs.length ? costs : u.sizes).map(s => ({
      models: s.models,
      composition: u.sizes.find(x => x.models === s.models)?.composition,
      points: costs.find(c => c.models === s.models)?.points ?? null,
      extraPoints: extra.find(c => c.models === s.models)?.points ?? null,
    }));
    // Imported datasheets carry their own weapon profiles; hand-written ones reference weapons.json by id.
    const legacy = u.weapons.length && typeof u.weapons[0] === 'string';
    const weapons = legacy
      ? u.weapons.filter(id => globalWeapons[id]).map(id => ({ id, ...globalWeapons[id], type: globalWeapons[id].profiles[0].range === 'Melee' ? 'melee' : 'ranged' }))
      : u.weapons;
    const weaponMap = new Map(weapons.map(w => [w.id, w]));
    // weapons only named in wargear options (e.g. "see Armoury card") fall back to weapons.json
    for (const opt of u.wargear ?? []) {
      for (const id of [...(opt.choices ?? []), opt.gives, opt.default]) {
        if (id && !weaponMap.has(id) && globalWeapons[id]) {
          weaponMap.set(id, { id, ...globalWeapons[id], type: globalWeapons[id].profiles[0].range === 'Melee' ? 'melee' : 'ranged' });
        }
      }
    }
    return {
      ...u,
      sizes,
      weapons,
      weaponMap,
      loadout: u.loadout ?? (legacy ? u.weapons : []),
      storeImage: images.units[u.id] ?? null,
      emblem,
      pointsVerified: verified.has(u.id),
    };
  });

  const enhancements = new Map();
  for (const d of faction.detachments) {
    for (const e of d.enhancements) {
      enhancements.set(e.id, {
        ...e,
        type: e.type ?? 'enhancement',
        detachmentId: d.id,
        points: points.enhancements[e.id] ?? 0,
      });
    }
  }

  const data = {
    entry,
    faction,
    units,
    unitsById: new Map(units.map(u => [u.id, u])),
    weapons: weaponsFile.weapons,
    enhancements,
    detachmentsById: new Map(faction.detachments.map(d => [d.id, d])),
    stratagems: stratagems.detachments,
    emblem,
    pointsMeta: { version: points.version, source: points.source },
  };
  factionCache.set(entry.id, data);
  return data;
}
